using NUnit.Framework;

namespace ApexForge.ProjectOptimizer.Tests
{
    public sealed class FixContractTests
    {
        [Test] public void ReviewFloorRejectsDiagnostic() => Assert.IsFalse(FixContract.MeetsReviewConfidence(OptimizationConfidence.Diagnostic));
        [Test] public void ReviewFloorAcceptsHeuristic() => Assert.IsTrue(FixContract.MeetsReviewConfidence(OptimizationConfidence.Heuristic));
        [Test] public void AutomaticFloorRejectsHeuristic() => Assert.IsFalse(FixContract.MeetsAutomaticConfidence(OptimizationConfidence.Heuristic));
        [Test] public void HighRiskRequiresVerifier() => Assert.IsTrue(FixContract.RequiresPostconditionVerifier(FixRisk.High));
        [Test] public void MediumRiskDoesNotRequireVerifier() => Assert.IsFalse(FixContract.RequiresPostconditionVerifier(FixRisk.Medium));
        [Test] public void UnknownSavingsAreNeverReported() { var issue = new OptimizationIssue { Basis = SavingsBasis.Unknown, EstimatedSavings = 1024 }; Assert.AreEqual(0L, FixContract.EffectiveSavings(issue, null)); }
        [Test] public void OptionSavingsOverrideIssueSavings() { var issue = new OptimizationIssue { Basis = SavingsBasis.Disk, EstimatedSavings = 1024 }; var option = new FixOption { Basis = SavingsBasis.Disk, EstimatedSavings = 256 }; Assert.AreEqual(256L, FixContract.EffectiveSavings(issue, option)); }
        [Test] public void ReviewRejectsDiagnosticIssue() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.Diagnostic, Fix = _ => { } }; Assert.IsFalse(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, null, out _)); }
        [Test] public void ReviewRejectsForeignOption() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.Heuristic, Fix = _ => { } }; var foreign = new FixOption { Label = "Foreign", Apply = _ => { } }; Assert.IsFalse(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, foreign, out _)); }
        [Test] public void HighRiskReviewNeedsVerifier() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High, Fix = _ => { } }; Assert.IsFalse(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, null, out _)); }
        [Test] public void HighRiskOptionRequiresBackup() { var option = new FixOption { Risk = FixRisk.High }; Assert.IsTrue(option.EffectiveBackupRequired(false, false)); }
        [Test] public void HighRiskIssueRequiresBackup() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High, Fix = _ => { }, Verify = _ => true }; Assert.IsTrue(FixContract.EffectiveBackupRequired(issue, null)); }
        [Test] public void HighRiskIssueCanExecuteOnlyWithBackupContract() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High, Fix = _ => { }, Verify = _ => true }; Assert.IsTrue(FixContract.EffectiveBackupRequired(issue, null)); Assert.IsTrue(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, null, out _)); }
        [Test] public void FixEngineBlocksHighRiskWhenBackupDisabled() { var issue = new OptimizationIssue { RuleId = "TEST", FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High, Fix = _ => { }, Verify = _ => true }; var entry = new AssetEntry { Path = "Assets/DefinitelyMissing_ProjectOptimizer_Test.asset" }; var report = FixEngine.Apply(new[] { new FixRequest { Entry = entry, Issue = issue } }, false, FixExecutionMode.ReviewSingle); Assert.AreEqual(1, report.Blocked); Assert.AreEqual(0, report.AppliedVerified + report.AppliedUnverified); }
        [Test] public void InheritedHighRiskOptionRequiresBackup() { var issue = new OptimizationIssue { Risk = FixRisk.High }; var option = new FixOption(); Assert.IsTrue(FixContract.EffectiveBackupRequired(issue, option)); }
        [Test] public void HighRiskOptionCannotInheritIssueVerifier() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High, Verify = _ => true }; var option = new FixOption { Apply = _ => { } }; issue.Options.Add(option); Assert.IsNull(FixContract.EffectiveVerify(issue, option)); Assert.IsFalse(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, option, out _)); }
        [Test] public void HighRiskOptionWithOwnVerifierCanExecute() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.High }; var option = new FixOption { Apply = _ => { }, Verify = _ => true }; issue.Options.Add(option); Assert.IsNotNull(FixContract.EffectiveVerify(issue, option)); Assert.IsTrue(FixContract.CanExecute(FixExecutionMode.ReviewSingle, issue, option, out _)); }
        [Test] public void MediumRiskOptionMayInheritIssueVerifier() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.HighConfidence, Risk = FixRisk.Medium, Verify = _ => true }; var option = new FixOption { Apply = _ => { } }; issue.Options.Add(option); Assert.IsNotNull(FixContract.EffectiveVerify(issue, option)); }
        [Test] public void SavingsAreCappedBySharedPool() { long memorySaved = 0, diskSaved = 0; var a = new OptimizationIssue { Basis = SavingsBasis.Disk, EstimatedSavings = 900 }; var b = new OptimizationIssue { Basis = SavingsBasis.Disk, EstimatedSavings = 900 }; long first = FixContract.AddCappedSavings(ref memorySaved, ref diskSaved, 0, 1000, a, null); long second = FixContract.AddCappedSavings(ref memorySaved, ref diskSaved, 0, 1000, b, null); Assert.AreEqual(900L, first); Assert.AreEqual(100L, second); Assert.AreEqual(1000L, first + second); Assert.AreEqual(1000L, diskSaved); }
        [Test] public void MissingSavingsBaseProducesNoAggregateSavings() { long memorySaved = 0, diskSaved = 0; var issue = new OptimizationIssue { Basis = SavingsBasis.Disk, EstimatedSavings = 900 }; Assert.AreEqual(0L, FixContract.AddCappedSavings(ref memorySaved, ref diskSaved, 0, 0, issue, null)); }
        [Test] public void DiagnosticReviewIsNotReviewFixable() { var issue = new OptimizationIssue { FixKind = FixKind.Review, Confidence = OptimizationConfidence.Diagnostic, Fix = _ => { } }; Assert.IsFalse(issue.ReviewFixable); }
        [Test] public void PersistedExecutionPresenceRoundTrips() { var option = new PersistedFixOption { ActionId = "a", HasVerifier = false, HasApply = true }; var json = UnityEngine.JsonUtility.ToJson(option); var restored = UnityEngine.JsonUtility.FromJson<PersistedFixOption>(json); Assert.IsFalse(restored.HasVerifier); Assert.IsTrue(restored.HasApply); }
    }
}
